<script setup lang="ts">
import { Head, router, useForm } from '@inertiajs/vue3'; import InventoryNav from '../../Components/Common/InventoryNav.vue';
interface Customer {id:number;code:string;name:string;legal_name:string|null;tax_id:string|null;phone:string|null;email:string|null;credit_limit:string;payment_terms_days:number;active:boolean}
defineProps<{customers:Customer[]}>(); const form=useForm({code:'',name:'',legal_name:'',tax_id:'',email:'',phone:'',address:'',credit_limit:0,payment_terms_days:0});
const submit=()=>form.post('/sales/customers',{onSuccess:()=>form.reset()}); const toggle=(c:Customer)=>router.patch(`/sales/customers/${c.id}/active`,{active:!c.active},{preserveScroll:true});
</script>
<template><Head title="Clientes"/><main class="page"><InventoryNav/><h1>Clientes</h1><p>Catálogo de clientes, límites y condiciones de crédito.</p><form class="card grid" @submit.prevent="submit"><label>Código *<input v-model="form.code" required></label><label>Nombre *<input v-model="form.name" required></label><label>Razón social<input v-model="form.legal_name"></label><label>RTN/identificación<input v-model="form.tax_id"></label><label>Correo<input v-model="form.email" type="email"></label><label>Teléfono<input v-model="form.phone"></label><label>Límite de crédito<input v-model.number="form.credit_limit" type="number" min="0" step=".01"></label><label>Días de crédito<input v-model.number="form.payment_terms_days" type="number" min="0"></label><label class="wide">Dirección<textarea v-model="form.address"/></label><button :disabled="form.processing">Guardar cliente</button><p class="error">{{Object.values(form.errors)[0]}}</p></form><section class="card"><h2>Clientes registrados</h2><div class="table"><table><thead><tr><th>Código</th><th>Nombre</th><th>Contacto</th><th>Crédito</th><th>Estado</th><th></th></tr></thead><tbody><tr v-for="c in customers" :key="c.id"><td>{{c.code}}</td><td>{{c.name}}</td><td>{{c.phone||c.email||'—'}}</td><td>{{c.credit_limit}} / {{c.payment_terms_days}} días</td><td>{{c.active?'Activo':'Inactivo'}}</td><td><button class="danger" @click="toggle(c)">{{c.active?'Desactivar':'Activar'}}</button></td></tr></tbody></table></div></section></main></template>
<style scoped>.page{max-width:1400px;margin:auto;padding:2rem}.card{padding:1.5rem;border:1px solid var(--p-content-border-color);border-radius:1rem;margin:1rem 0;background:var(--p-content-background)}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem}.wide{grid-column:1/-1}label{display:grid;gap:.4rem;font-weight:600}input,textarea{padding:.75rem;border:1px solid var(--p-content-border-color);border-radius:.5rem;background:transparent;color:inherit}textarea{min-height:5rem}button{width:max-content;padding:.7rem 1rem;border:0;border-radius:.5rem;background:var(--p-primary-color);color:var(--p-primary-contrast-color);font-weight:700}.danger{background:#ef4444;color:#fff}.table{overflow:auto}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:.8rem;border-bottom:1px solid var(--p-content-border-color)}.error{color:#ef4444}@media(max-width:700px){.grid{grid-template-columns:1fr}.wide{grid-column:auto}}</style>
